merge-two-bsts.ts:
import * as fs from "fs";
class TreeNode {
  val: number;
  left: TreeNode | null = null;
  right: TreeNode | null = null;
  constructor(val: number) { this.val = val; }
}
function build(tokens: string[]): TreeNode | null {
  if (tokens.length === 0 || tokens[0] === 'null') return null;
  const root = new TreeNode(Number(tokens[0]));
  const q = [root];
  let i = 1, head = 0;
  while (head < q.length && i < tokens.length) {
    const node = q[head++];
    if (i < tokens.length && tokens[i] !== 'null') { node.left = new TreeNode(Number(tokens[i])); q.push(node.left); }
    i++;
    if (i < tokens.length && tokens[i] !== 'null') { node.right = new TreeNode(Number(tokens[i])); q.push(node.right); }
    i++;
  }
  return root;
}
const L = fs.readFileSync(0, 'utf8').split('\n');
const root = build(L[0].trim().split(/\s+/).filter(Boolean));
const root2 = build((L[1] || '').trim().split(/\s+/).filter(Boolean));

function solve(root: TreeNode | null, root2: TreeNode | null): string {
  // TODO: run two iterative in-order walks side by side and always take the smaller current value — the merge step of merge sort
  return '';
}

console.log(String(solve(root, root2)));

