class ListNode {
  val: number;
  next: ListNode | null;
  constructor(val: number, next: ListNode | null = null) { this.val = val; this.next = next; }
}
function build(vals: number[]): ListNode | null { let head = null; for (let i = vals.length - 1; i >= 0; i--) head = new ListNode(vals[i], head); return head; }
function dump(head: ListNode | null): string { const out = []; for (let p: ListNode | null = head; p; p = p.next) out.push(p.val); return out.length ? out.join(' ') : 'EMPTY'; }
